SELECT N.NOTICE_NUM, N.TITLE, N.CONTENT, N.CATEGORY, N.REG_DATE, N.VIEW_COUNT, U.USER_ID
FROM TBL_NOTICE N JOIN TBL_USER U ON N.USER_ID = U.USER_ID
WHERE N.NOTICE_NUM = #{value}

mapper.update:

UPDATE TBL_NOTICE
SET TITLE = #{title}, CONTENT = #{content}, CATEGORY = #{category}
WHERE NOTICE_NUM = #{noticeNum}


UPDATE TBL_NOTICE
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE NOTICE_NUM = #{value}

mapper.select:


SELECT *
FROM (
	SELECT ROWNUM AS RNUM, A.*
	FROM (
		SELECT N.NOTICE_NUM, N.TITLE, N.CONTENT, N.CATEGORY, N.REG_DATE, N.VIEW_COUNT, U.USER_ID
		FROM TBL_NOTICE N JOIN TBL_USER U ON N.USER_ID = U.USER_ID
		WHERE N.NOTICE_NUM > 0





		ORDER BY N.NOTICE_NUM DESC
	) A
	WHERE ROWNUM <= #{pageEnd}
)
WHERE RNUM >= #{pageStart}
ORDER BY NOTICE_NUM DESC
